 links=[("Bank of England","South Sea Bubble","The South Sea Company was set up partly to rival the Bank in managing Britain's national debt."),
  ("Treaty of Utrecht","South Sea Bubble","The company's main trading asset was the slave-trading contract (asiento) Britain won at Utrecht; speculation in its shares became the bubble."),
  ("Watt's steam engine","First public steam railway","Decades of improvement after Watt's engine, especially high-pressure steam, made locomotives possible."),
  ("Adam Smith's Wealth of Nations","Revolutions of 1848; Communist Manifesto","Marx built on Smith's and Ricardo's economics but argued that capitalism exploited workers and would be overthrown."),
  ("First public steam railway","Transcontinental railroad","Railways spread from Britain worldwide; by 1869 one crossed North America."),
  ("Transcontinental railroad","Haymarket affair; AFL founded","Railroads created giant corporations and national labour markets; the Great Railroad Strike of 1877 began decades of labour conflict."),
  ("Haymarket affair; AFL founded","T. Roosevelt; Progressive Era","Labour violence, urban poverty and the power of big trusts pushed reformers to demand regulation."),
  ("T. Roosevelt; Progressive Era","Federal Reserve; income tax","After the Panic of 1907, Progressive reformers created a central bank and a federal income tax.")],
